import React, { useEffect, useState } from 'react'
import {
  Alert, Button, Card, DatePicker, Form, Input, Modal, Popconfirm,
  Select, Space, Table, Tag, message,
} from 'antd'
import { PlusOutlined, ReloadOutlined } from '@ant-design/icons'
import dayjs from 'dayjs'
import api from '../api'

const POSITIONS = ['厨师长', '厨师', '面点师', '帮厨', '洗碗工', '采购员', '仓管员', '服务员']

function certTag(days) {
  if (days === null || days === undefined) return <Tag color="red">未登记</Tag>
  if (days < 0) return <Tag color="red">已过期{-days}天</Tag>
  if (days <= 30) return <Tag color="orange">{days}天后到期</Tag>
  return <Tag color="green">剩余{days}天</Tag>
}

export default function StaffPage() {
  const [list, setList] = useState([])
  const [loading, setLoading] = useState(false)
  const [filters, setFilters] = useState({})
  const [modalOpen, setModalOpen] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form] = Form.useForm()

  const load = async () => {
    setLoading(true)
    try {
      setList(await api.get('/staff', { params: filters }))
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { load() }, [filters])

  const openCreate = () => {
    setEditing(null)
    form.resetFields()
    form.setFieldsValue({ status: '在职', gender: '男' })
    setModalOpen(true)
  }

  const openEdit = (record) => {
    setEditing(record)
    form.setFieldsValue({
      ...record,
      hire_date: record.hire_date ? dayjs(record.hire_date) : null,
      cert_issue_date: record.cert_issue_date ? dayjs(record.cert_issue_date) : null,
      cert_expiry_date: record.cert_expiry_date ? dayjs(record.cert_expiry_date) : null,
    })
    setModalOpen(true)
  }

  const submit = async () => {
    const values = await form.validateFields()
    const payload = {
      ...values,
      hire_date: values.hire_date?.format('YYYY-MM-DD'),
      cert_issue_date: values.cert_issue_date?.format('YYYY-MM-DD'),
      cert_expiry_date: values.cert_expiry_date?.format('YYYY-MM-DD'),
    }
    if (editing) {
      await api.put(`/staff/${editing.id}`, payload)
      message.success('人员信息已更新')
    } else {
      await api.post('/staff', payload)
      message.success('人员登记成功')
    }
    setModalOpen(false)
    load()
  }

  const expired = list.filter((s) => s.status === '在职' && s.cert_days_remaining !== null && s.cert_days_remaining < 0)
  const expiring = list.filter((s) => s.status === '在职' && s.cert_days_remaining !== null && s.cert_days_remaining >= 0 && s.cert_days_remaining <= 30)

  const columns = [
    { title: '姓名', dataIndex: 'name', width: 90, fixed: 'left' },
    { title: '性别', dataIndex: 'gender', width: 60 },
    { title: '岗位', dataIndex: 'position', width: 90, render: (v) => <Tag>{v}</Tag> },
    { title: '联系电话', dataIndex: 'phone', width: 120 },
    { title: '入职日期', dataIndex: 'hire_date', width: 105 },
    { title: '健康证编号', dataIndex: 'health_cert_no', width: 130, render: (v) => v || '-' },
    { title: '发证日期', dataIndex: 'cert_issue_date', width: 105, render: (v) => v || '-' },
    { title: '有效期至', dataIndex: 'cert_expiry_date', width: 105, render: (v) => v || '-' },
    { title: '证件状态', width: 120, render: (_, r) => certTag(r.cert_days_remaining) },
    { title: '在职状态', dataIndex: 'status', width: 90, render: (v) => (
      <Tag color={v === '在职' ? 'green' : 'default'}>{v}</Tag>
    ) },
    {
      title: '操作', width: 120, fixed: 'right',
      render: (_, r) => (
        <Space>
          <a onClick={() => openEdit(r)}>编辑</a>
          <Popconfirm title="确认删除该人员？" onConfirm={async () => { await api.delete(`/staff/${r.id}`); message.success('已删除'); load() }}>
            <a style={{ color: '#cf1322' }}>删除</a>
          </Popconfirm>
        </Space>
      ),
    },
  ]

  return (
    <Card
      title="从业人员健康证管理"
      extra={
        <Space>
          <Button icon={<ReloadOutlined />} onClick={load}>刷新</Button>
          <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}>人员登记</Button>
        </Space>
      }
    >
      {(expired.length > 0 || expiring.length > 0) && (
        <Alert
          style={{ marginBottom: 16 }}
          type={expired.length > 0 ? 'error' : 'warning'}
          showIcon
          message={
            expired.length > 0
              ? `${expired.map((s) => s.name).join('、')} 的健康证已过期，须立即调离岗位！`
              : `${expiring.map((s) => s.name).join('、')} 的健康证将在30天内到期，请安排体检换证`
          }
        />
      )}

      <Space wrap style={{ marginBottom: 16 }}>
        <Select allowClear placeholder="岗位" style={{ width: 110 }}
          options={POSITIONS.map((p) => ({ value: p, label: p }))}
          onChange={(v) => setFilters((f) => ({ ...f, position: v }))} />
        <Select allowClear placeholder="在职状态" style={{ width: 110 }}
          options={['在职', '离职'].map((s) => ({ value: s, label: s }))}
          onChange={(v) => setFilters((f) => ({ ...f, status: v }))} />
        <Input.Search allowClear placeholder="搜索姓名" style={{ width: 160 }}
          onSearch={(v) => setFilters((f) => ({ ...f, keyword: v || undefined }))} />
      </Space>

      <Table
        rowKey="id"
        size="small"
        loading={loading}
        columns={columns}
        dataSource={list}
        scroll={{ x: 1150 }}
        pagination={{ pageSize: 10, showTotal: (t) => `共 ${t} 条` }}
        rowClassName={(r) => (r.status === '在职' && r.cert_days_remaining !== null && r.cert_days_remaining < 0 ? 'row-expired' : '')}
      />

      <Modal
        title={editing ? '编辑人员信息' : '人员登记'}
        open={modalOpen}
        onOk={submit}
        onCancel={() => setModalOpen(false)}
        width={680}
        okText="保存"
        cancelText="取消"
        destroyOnClose
      >
        <Form form={form} layout="vertical" style={{ marginTop: 12 }}>
          <Space.Compact block>
            <Form.Item name="name" label="姓名" rules={[{ required: true, message: '请输入姓名' }]} style={{ flex: 1, marginRight: 12 }}>
              <Input />
            </Form.Item>
            <Form.Item name="gender" label="性别" style={{ width: 90, marginRight: 12 }}>
              <Select options={['男', '女'].map((g) => ({ value: g, label: g }))} />
            </Form.Item>
            <Form.Item name="position" label="岗位" rules={[{ required: true, message: '请选择' }]} style={{ flex: 1, marginRight: 12 }}>
              <Select options={POSITIONS.map((p) => ({ value: p, label: p }))} />
            </Form.Item>
            <Form.Item name="status" label="在职状态" rules={[{ required: true }]} style={{ width: 110 }}>
              <Select options={['在职', '离职'].map((s) => ({ value: s, label: s }))} />
            </Form.Item>
          </Space.Compact>
          <Space.Compact block>
            <Form.Item name="id_card" label="身份证号" style={{ flex: 1.4, marginRight: 12 }}>
              <Input maxLength={18} />
            </Form.Item>
            <Form.Item name="phone" label="联系电话" style={{ flex: 1, marginRight: 12 }}>
              <Input />
            </Form.Item>
            <Form.Item name="hire_date" label="入职日期" style={{ flex: 1 }}>
              <DatePicker style={{ width: '100%' }} />
            </Form.Item>
          </Space.Compact>
          <Space.Compact block>
            <Form.Item name="health_cert_no" label="健康证编号" style={{ flex: 1, marginRight: 12 }}>
              <Input placeholder="如：JK2025A0001" />
            </Form.Item>
            <Form.Item name="cert_issue_date" label="发证日期" style={{ flex: 1, marginRight: 12 }}>
              <DatePicker style={{ width: '100%' }} />
            </Form.Item>
            <Form.Item name="cert_expiry_date" label="有效期至（健康证有效期1年）" style={{ flex: 1 }}>
              <DatePicker style={{ width: '100%' }} />
            </Form.Item>
          </Space.Compact>
        </Form>
      </Modal>

      <style>{`.row-expired td { background: #fff1f0 !important; }`}</style>
    </Card>
  )
}

"""业务逻辑：预警计算、系统巡检（自动生成异常工单）"""
from datetime import date, datetime

from sqlalchemy.orm import Session

from .models import Incident, Purchase, Rectification, Sample, Staff

# 预警阈值常量
SAMPLE_RETENTION_HOURS = 48      # 留样保存时长(小时)
SAMPLE_WARN_HOURS = 2            # 留样到期前提醒(小时)
CERT_WARN_DAYS = 30              # 健康证到期前提醒(天)
PURCHASE_WARN_DAYS = 3           # 食材临期提醒(天)


def compute_alerts(db: Session) -> list[dict]:
    """汇总当前所有预警信息"""
    now = datetime.now()
    today = date.today()
    alerts: list[dict] = []

    # 1. 留样预警
    active_samples = db.query(Sample).filter(Sample.status == "留样中").all()
    for s in active_samples:
        remaining = (s.retention_deadline - now).total_seconds() / 3600
        if remaining < 0:
            alerts.append({
                "type": "sample", "level": "danger", "related_id": s.id,
                "title": f"留样超期未销毁：{s.dish_name}",
                "description": f"{s.meal_type}留样已于 {s.retention_deadline.strftime('%m-%d %H:%M')} 满48小时，请及时销毁并登记",
            })
        elif remaining <= SAMPLE_WARN_HOURS:
            alerts.append({
                "type": "sample", "level": "warning", "related_id": s.id,
                "title": f"留样即将到期：{s.dish_name}",
                "description": f"{s.meal_type}留样将于 {s.retention_deadline.strftime('%m-%d %H:%M')} 到期（剩余{remaining:.1f}小时）",
            })

    # 2. 健康证预警
    staff_list = db.query(Staff).filter(Staff.status == "在职").all()
    for st in staff_list:
        if not st.cert_expiry_date:
            continue
        days = (st.cert_expiry_date - today).days
        if days < 0:
            alerts.append({
                "type": "cert", "level": "danger", "related_id": st.id,
                "title": f"健康证已过期：{st.name}",
                "description": f"{st.position} {st.name} 的健康证已于 {st.cert_expiry_date} 过期{-days}天，须立即离岗并补办",
            })
        elif days <= CERT_WARN_DAYS:
            alerts.append({
                "type": "cert", "level": "warning", "related_id": st.id,
                "title": f"健康证即将到期：{st.name}",
                "description": f"{st.position} {st.name} 的健康证将于 {st.cert_expiry_date} 到期（剩余{days}天），请安排体检换证",
            })

    # 3. 食材保质期预警
    purchases = db.query(Purchase).filter(Purchase.status != "不合格", Purchase.expiry_date.isnot(None)).all()
    for p in purchases:
        days = (p.expiry_date - today).days
        if days < 0:
            alerts.append({
                "type": "purchase", "level": "danger", "related_id": p.id,
                "title": f"食材已过期：{p.ingredient_name}",
                "description": f"批次{p.batch_no or '-'}已于 {p.expiry_date} 过期{-days}天，请立即封存销毁",
            })
        elif days <= PURCHASE_WARN_DAYS:
            alerts.append({
                "type": "purchase", "level": "warning", "related_id": p.id,
                "title": f"食材临期：{p.ingredient_name}",
                "description": f"批次{p.batch_no or '-'}将于 {p.expiry_date} 到期（剩余{days}天），请优先使用",
            })

    # 4. 整改逾期预警
    rects = db.query(Rectification).filter(Rectification.status.in_(["待整改", "整改中", "已逾期"])).all()
    for r in rects:
        if r.deadline < today:
            alerts.append({
                "type": "rectification", "level": "danger", "related_id": r.id,
                "title": f"整改已逾期：{r.measures[:20]}...",
                "description": f"责任人 {r.responsible}，整改期限 {r.deadline}，已逾期{(today - r.deadline).days}天",
            })

    level_order = {"danger": 0, "warning": 1, "info": 2}
    alerts.sort(key=lambda a: level_order.get(a["level"], 3))
    return alerts


def run_inspection(db: Session) -> dict:
    """系统巡检：扫描问题并自动生成异常工单（已存在未关闭工单的则跳过）。
    返回新生成的工单摘要。"""
    today = date.today()
    created: list[Incident] = []

    def has_open_incident(related_type: str, related_id: int) -> bool:
        return db.query(Incident).filter(
            Incident.related_type == related_type,
            Incident.related_id == related_id,
            Incident.status.in_(["待处理", "整改中"]),
        ).first() is not None

    # 1. 健康证过期 -> 自动生成工单
    for st in db.query(Staff).filter(Staff.status == "在职").all():
        if st.cert_expiry_date and st.cert_expiry_date < today and not has_open_incident("staff", st.id):
            inc = Incident(
                title=f"健康证过期：{st.name}",
                category="健康证异常",
                description=f"系统巡检发现：{st.position} {st.name} 的健康证（{st.health_cert_no or '无证号'}）"
                            f"已于 {st.cert_expiry_date} 过期，违反《食品安全法》第四十五条，须立即调离岗位并补办。",
                severity="严重", reporter="系统", source="系统巡检",
                related_type="staff", related_id=st.id,
            )
            db.add(inc)
            created.append(inc)

    # 2. 食材过期 -> 自动生成工单
    for p in db.query(Purchase).filter(Purchase.status != "不合格", Purchase.expiry_date.isnot(None)).all():
        if p.expiry_date < today and not has_open_incident("purchase", p.id):
            inc = Incident(
                title=f"食材过期：{p.ingredient_name}",
                category="食材异常",
                description=f"系统巡检发现：{p.ingredient_name}（批次{p.batch_no or '-'}，存放于{p.storage_location or '-'}）"
                            f"已于 {p.expiry_date} 过期，请立即封存、销毁并核查库存。",
                severity="较重", reporter="系统", source="系统巡检",
                related_type="purchase", related_id=p.id,
            )
            db.add(inc)
            created.append(inc)

    # 3. 留样超期未销毁 -> 自动生成工单（超过48小时截止仍未销毁即触发）
    now = datetime.now()
    for s in db.query(Sample).filter(Sample.status == "留样中", Sample.retention_deadline < now).all():
        if not has_open_incident("sample", s.id):
            inc = Incident(
                title=f"留样超期未处理：{s.dish_name}",
                category="留样异常",
                description=f"系统巡检发现：{s.meal_type}留样「{s.dish_name}」（留样人{s.keeper or '-'}）"
                            f"已于 {s.retention_deadline.strftime('%Y-%m-%d %H:%M')} 满48小时，至今未销毁登记。",
                severity="一般", reporter="系统", source="系统巡检",
                related_type="sample", related_id=s.id,
            )
            db.add(inc)
            created.append(inc)

    # 4. 整改逾期 -> 更新状态并生成工单
    for r in db.query(Rectification).filter(Rectification.status.in_(["待整改", "整改中", "已逾期"])).all():
        if r.deadline < today:
            if r.status != "已逾期":
                r.status = "已逾期"
            if not has_open_incident("rectification", r.id):
                inc = Incident(
                    title=f"整改逾期未完成（工单#{r.id}）",
                    category="其他",
                    description=f"系统巡检发现：整改任务「{r.measures[:50]}」（责任人{r.responsible}）"
                                f"期限 {r.deadline} 已逾期{(today - r.deadline).days}天仍未完成。",
                    severity="较重", reporter="系统", source="系统巡检",
                    related_type="rectification", related_id=r.id,
                )
                db.add(inc)
                created.append(inc)

    db.commit()
    return {"created": len(created), "items": [{"id": i.id, "title": i.title} for i in created]}

