def delete_incident(incident_id: int, db: Session = Depends(get_db),
                    user: dict = ADMIN_ONLY):
    obj = db.get(Incident, incident_id)
    if not obj:
        raise HTTPException(404, "异常工单不存在")
    log_action(db, user, "删除工单", "incident", obj.id, f"删除工单「{obj.title}」")
    db.delete(obj)
    db.commit()


# ---------- 整改跟踪 ----------
