    obj = Rectification(**data.model_dump(), started_at=datetime.now(), status="整改中")
    incident.status = "整改中"
    db.add(obj)
    db.flush()
    log_action(db, user, "下达整改", "rectification", obj.id,
               f"就工单「{incident.title}」下达整改，责任人{obj.responsible}，期限{obj.deadline}")
    db.commit()
    db.refresh(obj)
